impl Default for UiTypography {
    fn default() -> Self {
        let style = |size: f32, line_height: f32| UiTextStyle {
            size: px(size),
            line_height: px(line_height),
        };
        Self {
            xs: style(12., 16.),
            sm: style(14., 20.),
            base: style(16., 24.),
            lg: style(18., 28.),
            xl: style(20., 28.),
        }
    }
}

